from jsonb_to_recordset($json$[{"id":"che-so-251","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Berkeley and Hartley devised a laboratory method to measure","options":["osmotic pressure","$K_H$","mass percent","electron spin"],"answer_index":0,"explanation":"Their apparatus applies a measured pressure to just stop osmosis.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-252","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At constant temperature, osmotic pressure of a dilute non-electrolyte is proportional to","options":["the molar concentration","the square of the concentration","1/C","the solvent $K_b$"],"answer_index":0,"explanation":"$\\pi = CRT$ at fixed T is a direct proportion between $\\pi$ and C.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-253","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 M non-electrolyte at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹) has $\\pi$ nearest","options":["2.46 atm","0.082 atm","3.00 atm","24.6 atm"],"answer_index":0,"explanation":"$\\pi = 0.10 \\times 0.0821 \\times 300 = 2.46$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-254","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose 18 g (180 g mol⁻¹) in 1.0 L at 27 °C (R = 0